function parseFromDisplayName(fromValue) {
  const trimmed = String(fromValue || '').trim();
  const match = trimmed.match(/^([^<]+)</);
  if (!match) return '';
  const name = match[1].trim().replace(/^["']|["']$/g, '');
  return name && !name.includes('@') ? name : '';
}

